INSERT INTO achievement_standard (code, subject, grade_band, area, statement, level_scale, levels, curriculum_version, source, note) VALUES
('2국01-01', '국어', '초1~2', '듣기⋅말하기', '중요한 내용이나 일이 일어난 순서를 고려하며 듣고 말한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국01-02', '국어', '초1~2', '듣기⋅말하기', '바르고 고운 말로 서로의 감정을 나누며 듣고 말한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국01-03', '국어', '초1~2', '듣기⋅말하기', '상대의 말을 집중하여 듣고 말차례를 지키며 대화한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국01-04', '국어', '초1~2', '듣기⋅말하기', '자신의 경험이나 생각을 바른 자세로 발표한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국01-05', '국어', '초1~2', '듣기⋅말하기', '듣기와 말하기에 관심과 흥미를 가진다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국02-01', '국어', '초1~2', '읽기', '글자, 단어, 문장, 짧은 글을 정확하게 소리 내어 읽는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국02-02', '국어', '초1~2', '읽기', '의미가 잘 드러나도록 문장과 짧은 글을 알맞게 띄어 읽는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국02-03', '국어', '초1~2', '읽기', '글을 읽고 중심 내용을 확인한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국02-04', '국어', '초1~2', '읽기', '인물의 마음이나 생각을 짐작하고 이를 자신과 비교하며 글을 읽는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국02-05', '국어', '초1~2', '읽기', '읽기에 흥미를 가지고 즐겨 읽는 태도를 지닌다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국03-01', '국어', '초1~2', '쓰기', '글자와 단어를 바르게 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국03-02', '국어', '초1~2', '쓰기', '쓰기에 흥미를 가지며 자신의 생각이나 느낌을 문장으로 표현한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국03-03', '국어', '초1~2', '쓰기', '주변 소재에 대해 소개하는 글을 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국03-04', '국어', '초1~2', '쓰기', '겪은 일을 표현하는 글을 자유롭게 쓰고, 쓴 글을 함께 읽고 생각이나 느낌을 나눈다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국04-01', '국어', '초1~2', '문법', '한글 자모의 이름과 소릿값을 알고 정확하게 발음하고 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국04-02', '국어', '초1~2', '문법', '소리와 표기가 다를 수 있음을 알고 단어를 바르게 읽고 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국04-03', '국어', '초1~2', '문법', '문장과 문장 부호를 알맞게 쓰고 한글에 호기심을 가진다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국05-01', '국어', '초1~2', '문학', '말놀이, 낭송 등을 통해 말의 재미와 즐거움을 느낀다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국05-02', '국어', '초1~2', '문학', '작품을 듣거나 읽으면서 느끼거나 생각한 점을 말한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국05-03', '국어', '초1~2', '문학', '작품 속 인물의 모습, 행동, 마음을 상상하여 시, 노래, 이야기, 그림 등으로 표현한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국05-04', '국어', '초1~2', '문학', '시나 노래, 이야기에 흥미를 가진다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국06-01', '국어', '초1~2', '매체', '일상의 다양한 매체와 매체 자료에 흥미와 관심을 가진다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2국06-02', '국어', '초1~2', '매체', '일상의 경험과 생각을 글과 그림으로 표현한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-01', '수학', '초1~2', '수와 연산', '수의 필요성을 인식하면서 0과 100까지의 수 개념을 이해하고, 수를 세고 읽고 쓸 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-02', '수학', '초1~2', '수와 연산', '일, 십, 백, 천의 자릿값과 위치적 기수법을 이해하고, 네 자리 이하의 수를 읽고 쓸 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-03', '수학', '초1~2', '수와 연산', '네 자리 이하의 수의 범위에서 수의 계열을 이해하고, 수의 크기를 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-04', '수학', '초1~2', '수와 연산', '하나의 수를 두 수로 분해하고 두 수를 하나의 수로 합성하는 활동을 통하여 수 감각을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-05', '수학', '초1~2', '수와 연산', '덧셈과 뺄셈이 이루어지는 실생활 상황과 연결하여 덧셈과 뺄셈의 의미를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-06', '수학', '초1~2', '수와 연산', '두 자리 수의 범위에서 덧셈과 뺄셈의 계산 원리를 이해하고 그 계산을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-07', '수학', '초1~2', '수와 연산', '덧셈과 뺄셈의 관계를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-08', '수학', '초1~2', '수와 연산', '두 자리 수의 범위에서 세 수의 덧셈과 뺄셈을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-09', '수학', '초1~2', '수와 연산', '□가 사용된 덧셈식과 뺄셈식을 만들고, □의 값을 구할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-10', '수학', '초1~2', '수와 연산', '곱셈이 이루어지는 실생활 상황과 연결하여 곱셈의 의미를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수01-11', '수학', '초1~2', '수와 연산', '곱셈구구를 이해하고, 한 자리 수의 곱셈을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수02-01', '수학', '초1~2', '변화와 관계', '물체, 무늬, 수 등의 배열에서 규칙을 찾아 여러 가지 방법으로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수02-02', '수학', '초1~2', '변화와 관계', '자신이 정한 규칙에 따라 물체, 무늬, 수 등을 배열할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-01', '수학', '초1~2', '도형과 측정', '교실 및 생활 주변에서 여러 가지 물건을 관찰하여 직육면체, 원기둥, 구의 모양을 찾고, 이를 이용하여 여러 가지 모양을 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-02', '수학', '초1~2', '도형과 측정', '쌓기나무를 이용하여 여러 가지 입체도형의 모양을 만들고, 그 모양에 대해 위치나 방향을 이용하여 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-03', '수학', '초1~2', '도형과 측정', '교실 및 생활 주변에서 여러 가지 물건을 관찰하여 삼각형, 사각형, 원의 모양을 찾고, 이를 이용하여 여러 가지 모양을 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-04', '수학', '초1~2', '도형과 측정', '삼각형, 사각형, 원을 직관적으로 이해하고, 그 모양을 그릴 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-05', '수학', '초1~2', '도형과 측정', '삼각형, 사각형에서 각각의 공통점을 찾아 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-06', '수학', '초1~2', '도형과 측정', '구체물의 길이, 들이, 무게, 넓이를 비교하여 각각 ‘길다, 짧다’, ‘많다, 적다’, ‘무겁다, 가볍다’, ‘넓다, 좁다’ 등을 구별하여 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-07', '수학', '초1~2', '도형과 측정', '시계를 보고 시각을 ‘몇 시 몇 분’까지 읽을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-08', '수학', '초1~2', '도형과 측정', '1시간과 1분의 관계를 이해하고, 시간을 ‘시간’, ‘분’으로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-09', '수학', '초1~2', '도형과 측정', '실생활 문제 상황과 연결하여 1분, 1시간, 1일, 1주일, 1개월, 1년 사이의 관계를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-10', '수학', '초1~2', '도형과 측정', '길이 단위 1cm와 1m를 알고, 이를 이용하여 주변 사물의 길이를 측정할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-11', '수학', '초1~2', '도형과 측정', '1m와 1cm의 관계를 이해하고, 길이를 ‘몇 m 몇 cm’와 ‘몇 cm’로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-12', '수학', '초1~2', '도형과 측정', '여러 가지 물건의 길이를 어림하고, 길이에 대한 양감을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수03-13', '수학', '초1~2', '도형과 측정', '실생활 문제 상황과 연결하여 길이의 덧셈과 뺄셈을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수04-01', '수학', '초1~2', '자료와 가능성', '여러 가지 사물을 정해진 기준 또는 자신이 정한 기준으로 분류하여 개수를 세어 보고, 기준에 따른 결과를 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수04-02', '수학', '초1~2', '자료와 가능성', '자료를 분류하여 표로 나타내고, 자료를 표로 나타내면 편리한 점을 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2수04-03', '수학', '초1~2', '자료와 가능성', '자료를 분류하여 ○, ×, / 등을 이용한 그래프로 나타내고, 자료를 그래프로 나타내면 편리한 점을 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바01-01', '바른 생활', '초1~2', '우리는 누구로 살아갈까', '학교 생활 습관과 학습 습관을 형성하여 안전하고 건강하게 생활한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바01-02', '바른 생활', '초1~2', '우리는 누구로 살아갈까', '나를 이해하고 존중하며 생활한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바01-03', '바른 생활', '초1~2', '우리는 누구로 살아갈까', '가족이나 주변 사람을 배려하며 관계를 맺는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바01-04', '바른 생활', '초1~2', '우리는 누구로 살아갈까', '생태환경에서 더불어 살기 위해 노력한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바02-01', '바른 생활', '초1~2', '우리는 어디서 살아갈까', '공동체에서 내가 할 수 있는 일을 찾아보고 실천한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바02-02', '바른 생활', '초1~2', '우리는 어디서 살아갈까', '우리나라의 소중함을 알고 사랑하는 마음을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바02-03', '바른 생활', '초1~2', '우리는 어디서 살아갈까', '차이나 다양성을 서로 존중하면서 생활한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('2바02-04', '바른 생활', '초1~2', '우리는 어디서 살아갈까', '새로운 활동에 호기심을 갖고 도전한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
