('4수04-03', '수학', '초3~4', '자료와 가능성', '탐구 문제를 해결하기 위해 자료를 수집, 정리하여 막대그래프나 꺾은선그래프로 나타내고 해석할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사01-01', '사회', '초3~4', '우리가 사는 곳', '주변 여러 장소에서의 경험과 느낌을 다양한 방식으로 표현하고, 장소감을 나누며 서로 존중하는 태도를 지닌다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사01-02', '사회', '초3~4', '우리가 사는 곳', '주변의 여러 장소를 살펴보고, 우리가 사는 곳을 더 살기 좋은 곳으로 만드는 방안을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사02-01', '사회', '초3~4', '일상에서 만나는 과거', '일상 속에서 시간의 흐름을 경험할 수 있는 사례를 살펴보고, 이를 바탕으로 역사의 시간 개념을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사02-02', '사회', '초3~4', '일상에서 만나는 과거', '오래된 물건이나 자료들을 주변에서 찾아보고, 이를 통해 과거의 모습을 살펴볼 수 있음을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사02-03', '사회', '초3~4', '일상에서 만나는 과거', '지역의 변화상을 보여주는 역사 자료를 분석하여 지역 사람들의 달라진 생활 모습을 파악한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사03-01', '사회', '초3~4', '사회 변화와 다양한 문화', '최근 사회 변화의 양상과 특징을 파악하고, 그로 인해 나타난 생활모습의 변화를 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사03-02', '사회', '초3~4', '사회 변화와 다양한 문화', '우리 사회에 다양한 문화가 확산되면서 나타나는 긍정적 효과와 문제를 분석하고, 나와 다른 사람이나 집단의 문화를 존중하는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사04-01', '사회', '초3~4', '옛날과 오늘날의 생활 모습', '옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사04-02', '사회', '초3~4', '옛날과 오늘날의 생활 모습', '옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사04-03', '사회', '초3~4', '옛날과 오늘날의 생활 모습', '옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사05-01', '사회', '초3~4', '지도로 만나는 우리 지역', '우리 지역을 표현한 다양한 종류의 지도를 찾아보고, 지도의 요소를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사05-02', '사회', '초3~4', '지도로 만나는 우리 지역', '지도에서 우리 지역의 위치를 파악하고, 우리 지역의 지리 정보를 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사06-01', '사회', '초3~4', '우리 지역의 문화유산', '지역의 문화유산을 통해 문화유산의 의미와 유형을 알아보고, 문화유산의 가치를 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사06-02', '사회', '초3~4', '우리 지역의 문화유산', '지역의 박물관, 기념관, 유적지 등을 체험하고 지역의 역사를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사07-01', '사회', '초3~4', '경제활동과 지역 간 교류', '자원의 희소성으로 인해 경제활동에서 선택의 문제가 발생함을 이해하고, 경제활동에서 합리적 선택의 방법을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사07-02', '사회', '초3~4', '경제활동과 지역 간 교류', '생산과 소비 활동을 파악하고, 인적⋅물적 교류의 사례를 통해 각 지역 및 사람들이 상호의존 관계를 맺고 있음을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 생산과 소비 활동을 파악하고, 인적ㆍ물적 교류의 사례를 통해 각 지역 및 사람들이 상호 의존 관계를 맺고 있음을 탐색한다.'),
('4사08-01', '사회', '초3~4', '민주주의와 자치', '학교 자치 사례를 통하여 민주주의의 의미를 이해하고, 학교생활에서 민주주의를 실천하는 능력을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사08-02', '사회', '초3~4', '민주주의와 자치', '지역에서 이루어지는 민주주의 사례를 통해 주민 자치와 주민 참여의 중요성을 파악하고, 지역사회의 문제 해결에 참여하는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사09-01', '사회', '초3~4', '지역문제를 해결하고 지역을 알리는 노력', '생활 주변에서 찾을 수 있는 여러 가지 문제를 파악하고, 그 문제를 합리적으로 해결하는 능력을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사09-02', '사회', '초3~4', '지역문제를 해결하고 지역을 알리는 노력', '지역의 자연환경, 역사, 문화, 생산물 등을 알리려는 지역사회의 노력을 알고 관심을 갖는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사10-01', '사회', '초3~4', '다양한 환경과 삶의 모습', '여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 변화를 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4사10-02', '사회', '초3~4', '다양한 환경과 삶의 모습', '사례에서 도시의 인구, 교통, 산업 등의 특징을 탐구하고, 도시에서의 삶의 모습을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과01-01', '과학', '초3~4', '힘과 우리 생활', '일상생활에서 힘과 관련된 현상에 흥미를 갖고, 물체를 밀거나 당길 때 나타나는 현상을 관찰할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과01-02', '과학', '초3~4', '힘과 우리 생활', '수평잡기 활동을 통해 물체의 무게를 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과01-03', '과학', '초3~4', '힘과 우리 생활', '무게를 정확히 비교하기 위해서는 저울이 필요함을 알고, 저울을 사용해 무게를 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과01-04', '과학', '초3~4', '힘과 우리 생활', '지레, 빗면과 같은 도구를 이용하면 물체를 들어 올릴 때 드는 힘의 크기가 달라짐을 알고, 도구가 일상생활에서 어떻게 쓰이는지 조사하여 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과02-01', '과학', '초3~4', '동물의 생활', '여러 가지 동물을 관찰하여 특징에 따라 동물을 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과02-02', '과학', '초3~4', '동물의 생활', '다양한 환경에 서식하는 동물을 조사하여 동물의 생김새와 생활 방식이 환경과 관련되어 있음을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과02-03', '과학', '초3~4', '동물의 생활', '동물의 특징을 이용하여 일상생활에서 활용할 수 있는 생활용품을 설계하여 협력적으로 소통할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과03-01', '과학', '초3~4', '식물의 생활', '여러 가지 식물을 관찰하여 특징에 따라 식물을 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과03-02', '과학', '초3~4', '식물의 생활', '다양한 환경에 서식하는 식물을 조사하여 식물의 생김새와 생활 방식이 환경과 관련되어 있음을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과03-03', '과학', '초3~4', '식물의 생활', '식물의 특징을 이용하여 일상생활에서 활용할 수 있는 생활용품을 설계하여 협력적으로 소통할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과04-01', '과학', '초3~4', '생물의 한살이', '동물의 한살이를 직접 관찰하고, 관찰한 내용을 글과 그림으로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과04-02', '과학', '초3~4', '생물의 한살이', '식물이 자라는 데 필요한 조건을 찾는 실험을 설계하여 수행할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과04-03', '과학', '초3~4', '생물의 한살이', '생물의 한살이 과정을 조사하여 생물에 따라 한살이의 유형이 다양함을 소개하는 자료를 만들어 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과05-01', '과학', '초3~4', '물체와 물질', '물체를 이루는 여러 가지 물질의 성질을 비교하고, 물질의 종류에 따라 물체를 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과05-02', '과학', '초3~4', '물체와 물질', '물질의 세 가지 상태인 고체, 액체, 기체의 성질을 관찰하여 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과05-03', '과학', '초3~4', '물체와 물질', '다양한 물질의 성질을 이용하여 쓰임새 있는 물체를 설계할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과06-01', '과학', '초3~4', '지구와 바다', '지구가 대기로 둘러싸여 있음을 알고, 지구 표면을 구성하는 육지와 바다의 특징을 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과06-02', '과학', '초3~4', '지구와 바다', '바닷물의 특징을 육지의 물과 비교하고, 바닷가에서 볼 수 있는 다양한 지형을 조사할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과06-03', '과학', '초3~4', '지구와 바다', '밀물과 썰물의 차이를 알고, 갯벌의 가치와 보전의 필요성을 설득⋅홍보할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과07-01', '과학', '초3~4', '소리의 성질', '여러 가지 물체를 이용하여 소리를 내보고, 소리가 나는 물체는 떨림이 있음을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과07-02', '과학', '초3~4', '소리의 성질', '큰 소리와 작은 소리, 높은 소리와 낮은 소리를 구분하고, 세기와 높낮이가 다른 소리를 낼 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과07-03', '과학', '초3~4', '소리의 성질', '여러 가지 물질을 통하여 소리가 전달되는 것을 관찰하고, 소음을 줄이는 방법을 찾아 일상생활에서 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과08-01', '과학', '초3~4', '감염병과 건강한 생활', '생활 속 감염병의 사례를 알고, 다양한 질병과 그 위험성에 대해 토의할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과08-02', '과학', '초3~4', '감염병과 건강한 생활', '감염병으로부터 안전한 사회에 관심을 가지고, 여러 감염 과정을 통해 생활 습관과 감염병 유행과의 연관성을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과08-03', '과학', '초3~4', '감염병과 건강한 생활', '건강한 생활을 위해 필요한 감염병 예방 수칙을 공유하고, 생활 속에서 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과09-01', '과학', '초3~4', '자석의 이용', '자석과 여러 가지 물체를 가까이했을 때 나타나는 현상을 관찰하고, 자석과 자석에 붙는 물체 사이에 작용하는 힘의 특징을 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과09-02', '과학', '초3~4', '자석의 이용', '자석과 자석을 가까이했을 때 나타나는 현상을 관찰하여 그 특징을 자석의 극과 관련지어 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과09-03', '과학', '초3~4', '자석의 이용', '자석을 이용하여 일상생활을 편리하게 하는 장치를 설계할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과10-01', '과학', '초3~4', '물의 상태 변화', '물이 세 가지 상태로 변할 수 있음을 알고, 우리 주변에서 예를 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과10-02', '과학', '초3~4', '물의 상태 변화', '물이 얼 때, 얼음이 녹을 때, 물이 증발할 때와 끓을 때, 수증기가 응결할 때의 변화를 관찰할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과10-03', '과학', '초3~4', '물의 상태 변화', '물의 상태 변화를 이용하여 물을 얻을 수 있는 장치를 설계하고 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과11-01', '과학', '초3~4', '땅의 변화', '흐르는 물의 작용과 강 주변 지형의 특징을 관련지을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과11-02', '과학', '초3~4', '땅의 변화', '화산의 의미와 화산 활동으로 나오는 물질을 알고, 화산 활동을 모형으로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과11-03', '과학', '초3~4', '땅의 변화', '화성암을 관찰하고 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과11-04', '과학', '초3~4', '땅의 변화', '화산 활동과 지진이 우리 생활에 미치는 영향을 조사하여, 대처 방법을 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과12-01', '과학', '초3~4', '다양한 생물과 우리 생활', '균류⋅원생생물⋅세균을 관찰하여 특징과 사는 곳을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과12-02', '과학', '초3~4', '다양한 생물과 우리 생활', '균류⋅원생생물⋅세균이 우리 생활에 미치는 영향을 조사하여 발표할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과12-03', '과학', '초3~4', '다양한 생물과 우리 생활', '우리 생활에 생명과학이 이용되는 사례를 소개하는 자료를 만들어 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과13-01', '과학', '초3~4', '밤하늘 관찰', '달의 모양과 표면, 달의 위상변화를 관찰하여 밤하늘 관찰에 흥미를 가질 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과13-02', '과학', '초3~4', '밤하늘 관찰', '태양계 구성원을 알고, 태양과 행성을 조사할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과13-03', '과학', '초3~4', '밤하늘 관찰', '별의 정의를 알고, 북극성 주변의 별자리를 관찰할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과14-01', '과학', '초3~4', '생물과 환경', '생태계의 구성 요소를 조사하여 생물 요소와 비생물 요소로 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과14-02', '과학', '초3~4', '생물과 환경', '생물 요소들의 먹고 먹히는 관계를 조사하여 먹이그물로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과14-03', '과학', '초3~4', '생물과 환경', '인간 활동이 생태계에 미치는 영향을 조사하고, 생태계 보전을 위해 우리가 할 수 있는 일을 토의하여 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과15-01', '과학', '초3~4', '여러 가지 기체', '실험을 통해 기체가 무게가 있음을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과15-02', '과학', '초3~4', '여러 가지 기체', '온도나 압력에 따라 기체의 부피가 달라지는 현상을 관찰하고, 우리 주변에서 예를 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과15-03', '과학', '초3~4', '여러 가지 기체', '일상생활에서 이용되는 기체의 종류와 성질을 조사하고, 여러 가지 기체에 대해 흥미를 느낄 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과15-04', '과학', '초3~4', '여러 가지 기체', '기체의 성질을 이용하여 작동시킬 수 있는 장치를 설계하고 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과16-01', '과학', '초3~4', '기후변화와 우리 생활', '기후변화 현상의 예를 알고, 기후변화가 인간의 활동과 관련되어 있음을 토의할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과16-02', '과학', '초3~4', '기후변화와 우리 생활', '기후변화의 심각성에 관심을 가지고, 기후변화가 우리 생활과 환경에 미치는 영향을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4과16-03', '과학', '초3~4', '기후변화와 우리 생활', '기후변화 대응 방법을 조사하고, 생활 속에서 기후변화 대응 방법을 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도01-01', '도덕', '초3~4', '자신과의 관계', '자신의 감정을 소중히 여기며 존중하는 태도를 바탕으로 내가 누구인가를 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도01-02', '도덕', '초3~4', '자신과의 관계', '정직의 의미를 알고 모범적인 사례를 탐색하여 바르게 행동하려는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도01-03', '도덕', '초3~4', '자신과의 관계', '성실한 생활의 모범 사례를 탐색하고 시간 관리를 위한 생활을 계획하여 지속적인 자기 성장을 모색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도01-04', '도덕', '초3~4', '자신과의 관계', '다른 사람의 관점을 수용할 수 있는지를 도덕적으로 검토하고 도덕규범을 내면화하여 도덕적으로 행동할 수 있는 자세를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도02-01', '도덕', '초3~4', '타인과의 관계', '효, 우애의 의미와 필요성을 명료하게 이해하고 가족의 행복을 위해 할 수 있는 일을 탐색하여 실천 계획을 세운다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도02-02', '도덕', '초3~4', '타인과의 관계', '친구 사이의 배려에 대한 올바른 이해를 바탕으로 일상생활에서 배려에 기반한 도덕적 관계를 맺을 수 있는 방안을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도02-03', '도덕', '초3~4', '타인과의 관계', '공감의 태도가 필요한 이유를 이해하고 도덕적 상상력을 바탕으로 대상과 상황에 따라 감정을 나누는 방법을 탐구하여 실천한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도03-01', '도덕', '초3~4', '사회⋅공동체와의 관계', '불공정의 사례를 탐구하고, 일상생활에서 공정의 가치를 추구하는 활동을 통해 실천 의지를 함양한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도03-02', '도덕', '초3~4', '사회⋅공동체와의 관계', '디지털 사회에서 발생하는 다양한 문제를 살펴보고, 해결 방안을 탐구하여 정보통신 윤리에 대한 민감성을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도03-03', '도덕', '초3~4', '사회⋅공동체와의 관계', '통일의 필요성을 이해하고, 통일 감수성을 길러 바람직한 통일의 방향을 모색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도04-01', '도덕', '초3~4', '자연과의 관계', '생명 경시 사례를 조사하고 문제 해결 방법을 탐구함으로써 생명의 소중함을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('4도04-02', '도덕', '초3~4', '자연과의 관계', '인간과 자연이 함께 살아야 하는 이유를 이해하고 공생을 위한 구체적인 실천 계획을 세우며 생태 감수성을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-01', '국어', '초5~6', '듣기⋅말하기', '대화에서 생략된 내용을 추론하며 듣는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-02', '국어', '초5~6', '듣기⋅말하기', '주장을 파악하고 이유나 근거가 타당한지 평가하며 듣는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-03', '국어', '초5~6', '듣기⋅말하기', '주제와 관련하여 궁금한 내용을 질문하며 적극적으로 듣고 말한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-04', '국어', '초5~6', '듣기⋅말하기', '면담의 절차를 이해하고 상대와 매체를 고려하여 면담한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-05', '국어', '초5~6', '듣기⋅말하기', '자료를 선별하여 핵심 정보를 중심으로 내용을 구성하고 매체를 활용하여 발표한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-06', '국어', '초5~6', '듣기⋅말하기', '토의에 협력적으로 참여하며 서로의 의견을 비교하고 조정한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국01-07', '국어', '초5~6', '듣기⋅말하기', '절차와 규칙을 지키고 타당한 이유와 근거를 제시하며 토론한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국02-01', '국어', '초5~6', '읽기', '글의 구조를 고려하며 주제나 주장을 파악하고 글 내용을 요약한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국02-02', '국어', '초5~6', '읽기', '글에서 생략된 내용이나 함축된 표현을 문맥을 고려하여 추론한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국02-03', '국어', '초5~6', '읽기', '글이나 자료를 읽고 내용의 타당성과 표현의 적절성을 평가한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국02-04', '국어', '초5~6', '읽기', '문제 상황과 관련된 다양한 관점의 글을 읽고 이를 문제 해결에 활용한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국02-05', '국어', '초5~6', '읽기', '긍정적인 읽기 동기를 형성하고 적극적으로 읽기에 참여하는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-01', '국어', '초5~6', '쓰기', '알맞은 내용을 선정하여 대상의 특성이 나타나게 설명하는 글을 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-02', '국어', '초5~6', '쓰기', '적절한 근거를 사용하고 인용의 출처를 밝히며 주장하는 글을 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-03', '국어', '초5~6', '쓰기', '체험한 일에 대한 감상을 나타내는 글을 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-04', '국어', '초5~6', '쓰기', '독자와 매체를 고려하여 내용을 생성하고 표현하며 글을 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-05', '국어', '초5~6', '쓰기', '쓰기 과정을 점검⋅조정하며 글을 쓰고, 글 전체를 대상으로 통일성 있게 고쳐 쓴다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국03-06', '국어', '초5~6', '쓰기', '쓰기에 적극적으로 참여하며 자신의 글을 독자와 공유하는 태도를 지닌다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-01', '국어', '초5~6', '문법', '음성 언어 및 문자 언어의 특성을 이해하고 다양한 매체 자료에서 표현 효과를 평가한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-02', '국어', '초5~6', '문법', '표준어와 방언의 기능을 파악하고 언어 공동체와 국어생활과의 관계를 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-03', '국어', '초5~6', '문법', '고유어와 관용 표현의 쓰임과 가치를 이해하고 상황에 맞게 표현한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-04', '국어', '초5~6', '문법', '문장 성분을 이해하고 호응 관계가 올바른 문장을 구성한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-05', '국어', '초5~6', '문법', '글과 담화에 쓰인 시간 표현을 이해하고 상황에 맞게 표현한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국04-06', '국어', '초5~6', '문법', '글과 담화에 쓰인 단어 및 문장, 띄어쓰기를 민감하게 살펴 바르게 고치는 태도를 지닌다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국05-01', '국어', '초5~6', '문학', '작가의 의도를 생각하며 작품을 읽는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
