('6국06-03', '국어', '초5~6', '매체', '적합한 양식과 수용자의 반응을 고려하여 복합양식 매체 자료를 제작하고 공유한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6국06-04', '국어', '초5~6', '매체', '자신의 매체 이용 양상에 대해 성찰한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-01', '수학', '초5~6', '수와 연산', '덧셈, 뺄셈, 곱셈, 나눗셈의 혼합 계산에서 계산하는 순서를 알고, 혼합 계산을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-02', '수학', '초5~6', '수와 연산', '실생활과 연결하여 이상, 이하, 초과, 미만의 의미와 쓰임을 알고, 이를 활용하여 수의 범위를 나타낼 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-03', '수학', '초5~6', '수와 연산', '어림값을 구하기 위한 방법으로 올림, 버림, 반올림의 의미와 필요성을 알고, 이를 실생활에 활용함으로써 수학의 유용성을 인식할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-04', '수학', '초5~6', '수와 연산', '약수, 공약수, 최대공약수를 이해하고 구할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-05', '수학', '초5~6', '수와 연산', '배수, 공배수, 최소공배수를 이해하고 구할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수01-06', '수학', '초5~6', '수와 연산', '크기가 같은 분수를 만드는 방법을 이해하고, 분수를 약분, 통분할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
