('6수01-15', '수학', '초5~6', '수와 연산', '소수의 나눗셈의 계산 원리를 탐구하고 그 계산을 할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수02-01', '수학', '초5~6', '변화와 관계', '한 양이 변할 때 다른 양이 그에 종속하여 변하는 대응 관계를 나타낸 표에서 규칙을 찾아 설명하고, □, △ 등을 사용하여 식으로 나타낼 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수02-02', '수학', '초5~6', '변화와 관계', '두 양의 크기를 비교하는 상황을 통해 비의 개념을 이해하고, 두 양의 관계를 비로 나타낼 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
