('6수03-19', '수학', '초5~6', '도형과 측정', '직육면체와 정육면체의 부피를 구하는 방법을 이해하고, 이를 구할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수04-01', '수학', '초5~6', '자료와 가능성', '평균의 의미를 알고, 자료를 수집하여 평균을 구하고 해석할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수04-02', '수학', '초5~6', '자료와 가능성', '자료를 수집하여 띠그래프나 원그래프로 나타내고 해석할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수04-03', '수학', '초5~6', '자료와 가능성', '탐구 문제를 설정하고, 그에 맞는 자료를 수집, 정리하여 적절한 그래프로 나타내고 해석할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수04-04', '수학', '초5~6', '자료와 가능성', '사건이 일어날 가능성을 말로 표현하고 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6수04-05', '수학', '초5~6', '자료와 가능성', '사건이 일어날 가능성을 수로 나타낼 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 C는 PDF 표가 뒤섞여 직접 확인해 넣음'),
('6수04-06', '수학', '초5~6', '자료와 가능성', '자료를 이용하여 가능성을 예상하고, 가능성에 근거하여 적절한 판단을 내릴 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 A는 PDF 표가 뒤섞여 직접 확인해 넣음'),
('6사01-01', '사회', '초5~6', '우리나라 국토 여행', '우리나라 산지, 하천, 해안 지형의 위치를 확인하고 지형의 분포 특징을 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사01-02', '사회', '초5~6', '우리나라 국토 여행', '독도의 지리적 특성과 독도에 대한 역사 기록을 바탕으로 영토로서 독도의 중요성을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사02-01', '사회', '초5~6', '우리나라 지리 탐구', '우리나라의 계절별 기후 특징을 자료에서 탐구하고, 기후변화로 인한 자연재해의 심각성을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사02-02', '사회', '초5~6', '우리나라 지리 탐구', '우리나라의 지역별 인구 분포의 특징을 알아보고, 이에 따른 문제점과 해결 방안을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사03-01', '사회', '초5~6', '법과 인권의 보장', '일상 사례에서 법의 의미와 역할을 이해하고, 헌법에 규정된 인권이 일상생활에서 구현되는 사례를 조사하여 인권 친화적 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사03-02', '사회', '초5~6', '법과 인권의 보장', '일상생활에서 인권이 침해되는 사례를 찾아 그 해결 방안을 탐색하고, 인권을 보호하는 활동에 참여한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사04-01', '사회', '초5~6', '유적과 유물로 살펴본 옛 사람들의 생활', '선사 시대와 고조선의 유적과 유물을 활용하여 당시 사람들의 생활을 추론한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사04-02', '사회', '초5~6', '유적과 유물로 살펴본 옛 사람들의 생활', '역사 기록이나 유적과 유물에 나타난 고대 사람들의 생각과 생활을 추론한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사04-03', '사회', '초5~6', '유적과 유물로 살펴본 옛 사람들의 생활', '다양한 역사 자료를 활용하여 고려 시대 사회 모습과 사람들의 생활을 추론한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사05-01', '사회', '초5~6', '달라지는 시대, 변화하는 생활 모습', '조선 시대 사람들의 생각과 생활에 유교 문화가 미친 영향을 파악한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사05-02', '사회', '초5~6', '달라지는 시대, 변화하는 생활 모습', '조선 후기 사회⋅문화적 변화와 개항기 근대 문물 수용 과정에서 달라진 사람들의 생활을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사06-01', '사회', '초5~6', '식민 통치와 저항, 전쟁이 바꾼 사회와 생활', '일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사06-02', '사회', '초5~6', '식민 통치와 저항, 전쟁이 바꾼 사회와 생활', '8⋅15 광복과 6⋅25 전쟁이 사회와 생활에 미친 영향을 파악한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사07-01', '사회', '초5~6', '평화 통일을 위한 노력, 민주화와 산업화', '분단으로 나타난 문제점과 분단과 관련된 장소를 평화의 장소로 만들려는 노력 등을 알아보고, 평화 통일을 위해 우리가 할 수 있는 일을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사07-02', '사회', '초5~6', '평화 통일을 위한 노력, 민주화와 산업화', '민주화와 산업화로 인해 달라진 생활 문화를 사례를 들어 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사08-01', '사회', '초5~6', '민주주의와 시민 참여', '민주주의에서 선거의 의미와 역할을 파악하고, 시민의 주권 행사를 위해 선거에 참여하는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사08-02', '사회', '초5~6', '민주주의와 시민 참여', '민주 국가에서 국회, 행정부, 법원이 하는 일에 대해 이해하고, 각 국가기관의 권력을 분립하는 이유를 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사08-03', '사회', '초5~6', '민주주의와 시민 참여', '민주주의에서 미디어의 의미와 역할을 이해하고, 여러 가지 미디어의 내용을 비판적으로 분석하여 올바르게 이용하는 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사09-01', '사회', '초5~6', '지구, 대륙 그리고 국가들', '세계를 표현하는 다양한 공간 자료의 특징을 이해하고, 지구본과 세계지도에서 위치를 표현하는 방법을 익힌다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사09-02', '사회', '초5~6', '지구, 대륙 그리고 국가들', '세계 주요 대륙과 대양을 파악하고, 우리나라 및 세계 여러 국가의 위치와 영토의 특징을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사10-01', '사회', '초5~6', '세계의 자연환경', '세계의 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 세계 여러 지역의 지형 경관을 살펴보고, 이를 통해 다양한 삶의 모습을 이해한다.'),
('6사10-02', '사회', '초5~6', '세계의 자연환경', '세계의 다양한 기후를 알아보고 기후 환경과 인간생활 간의 관계를 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사11-01', '사회', '초5~6', '시장경제와 국가 간 거래', '시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 사회적 책임을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 시장경제에서 가계와 기업의 역할을 이해하고, 근로자의 권리와 기업의 자유 및 책임을 탐색한다.'),
('6사11-02', '사회', '초5~6', '시장경제와 국가 간 거래', '경제성장이 우리 생활에 미치는 영향을 파악하고, 빠른 경제성장으로 발생한 문제의 해결 방안을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사11-03', '사회', '초5~6', '시장경제와 국가 간 거래', '사례를 통해 무역의 의미를 이해하고, 국가 간 무역이 발생하는 이유를 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6사12-01', '사회', '초5~6', '지구촌 사람들', '세계의 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 세계 인구 분포를 파악하고 여러 국가의 인구 특징을 탐구한다.'),
('6사12-02', '사회', '초5~6', '지구촌 사람들', '지구촌을 위협하는 다양한 문제들을 파악하고, 지속가능한 미래를 위한 해결 방안을 탐색한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과01-01', '과학', '초5~6', '지층과 화석', '지층의 특징을 알고, 지층의 형성 과정을 모형으로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과01-02', '과학', '초5~6', '지층과 화석', '지층이 퇴적암으로 이루어짐을 알고, 퇴적암을 알갱이의 크기에 따라 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과01-03', '과학', '초5~6', '지층과 화석', '화석의 생성 과정을 모형으로 설명하고, 지구의 과거 생물과 환경을 추리하는 활동을 통해 화석의 가치를 인식할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과02-01', '과학', '초5~6', '빛의 성질', '물체를 보기 위해서 빛이 있어야 함을 알고, 빛의 성질에 대해 흥미를 느낄 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과02-02', '과학', '초5~6', '빛의 성질', '빛이 나아가는 현상을 관찰하여 빛이 직진, 반사, 굴절하는 성질이 있음을 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과02-03', '과학', '초5~6', '빛의 성질', '거울과 렌즈의 쓰임새를 조사하고 거울이나 렌즈를 이용한 장치를 창의적으로 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과03-01', '과학', '초5~6', '용해와 용액', '용해 현상의 의미를 알고, 용질의 종류와 물의 온도에 따라 물에 녹는 용질의 양이 달라짐을 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과03-02', '과학', '초5~6', '용해와 용액', '용질이나 용매의 양에 따라 용액의 진하기가 달라짐을 관찰하고, 용액의 상대적인 진하기를 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과03-03', '과학', '초5~6', '용해와 용액', '일상생활에서 용액이 쓰이는 사례를 조사하여 용액의 필요성을 알리는 자료를 만들고 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과04-01', '과학', '초5~6', '우리 몸의 구조와 기능', '뼈와 근육의 생김새를 관찰하고 모형을 만들어 몸이 움직이는 원리를 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과04-02', '과학', '초5~6', '우리 몸의 구조와 기능', '소화, 순환, 호흡, 배설 기관의 구조와 기능을 알아보고, 우리 몸의 여러 기관이 서로 관련되어 있음을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과04-03', '과학', '초5~6', '우리 몸의 구조와 기능', '우리 몸의 여러 기관과 관련된 질병을 조사하고, 건강을 유지하기 위한 생활 방식을 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과05-01', '과학', '초5~6', '혼합물의 분리', '알갱이의 크기가 다른 고체 혼합물과 골고루 섞이지 않는 액체 혼합물을 분리할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과05-02', '과학', '초5~6', '혼합물의 분리', '물에 용해되는 성질을 이용하여 고체 혼합물을 분리하고, 물을 증발시켜 물에 용해된 고체 물질을 분리할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과05-03', '과학', '초5~6', '혼합물의 분리', '지속가능한 삶을 위한 과학기술 사례 중 혼합물의 분리를 이용한 장치를 조사하여 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과06-01', '과학', '초5~6', '날씨와 우리 생활', '기상 요소를 조사하고, 날씨가 우리 생활에 주는 영향을 인식할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과06-02', '과학', '초5~6', '날씨와 우리 생활', '이슬, 안개, 구름을 관찰하고, 공통점과 차이점을 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과06-03', '과학', '초5~6', '날씨와 우리 생활', '고기압과 저기압의 분포에 따른 날씨의 특징을 기상 요소로 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과07-01', '과학', '초5~6', '열과 우리 생활', '물체의 따뜻하고 차가운 정도를 온도로 표현함을 알고, 온도계를 이용하여 온도를 측정할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과07-02', '과학', '초5~6', '열과 우리 생활', '온도가 다른 두 물체가 접촉했을 때 두 물체의 온도 변화를 관찰하고 그 원인을 추리할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과07-03', '과학', '초5~6', '열과 우리 생활', '주위에서 열의 이동으로 나타나는 현상을 관찰하여 열의 이동 방식이 다양함을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과07-04', '과학', '초5~6', '열과 우리 생활', '일상생활에서 단열을 이용하는 사례를 조사하고, 온도를 오랫동안 일정하게 유지할 수 있는 장치를 창의적으로 만들 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과08-01', '과학', '초5~6', '자원과 에너지', '우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과08-02', '과학', '초5~6', '자원과 에너지', '재생에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과08-03', '과학', '초5~6', '자원과 에너지', '자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과09-01', '과학', '초5~6', '산과 염기', '여러 가지 용액에 지시약을 넣었을 때의 변화를 관찰하여 용액을 산성 용액과 염기성 용액으로 분류할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과09-02', '과학', '초5~6', '산과 염기', '산성 용액과 염기성 용액의 성질을 관찰하고, 산성 용액과 염기성 용액을 섞을 때 용액의 성질 변화를 실험을 통해 추론할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과09-03', '과학', '초5~6', '산과 염기', '우리 주변에서 산성 용액과 염기성 용액을 이용하는 예를 찾아서 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과09-04', '과학', '초5~6', '산과 염기', '산성화로 인한 환경의 피해 사례를 소개하는 자료를 만들고 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과10-01', '과학', '초5~6', '물체의 운동', '운동하는 물체는 시간에 따라 위치가 변화함을 알고 그 변화를 표현할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과10-02', '과학', '초5~6', '물체의 운동', '물체의 이동 거리와 걸린 시간을 측정하여 속력을 구하고 빠르기를 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과10-03', '과학', '초5~6', '물체의 운동', '속력과 관련된 안전 수칙과 안전장치를 조사한 결과를 공유하고 일상생활에서 교통안전을 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과11-01', '과학', '초5~6', '식물의 구조와 기능', '생물을 이루고 있는 기본 단위인 세포를 현미경으로 관찰할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과11-02', '과학', '초5~6', '식물의 구조와 기능', '식물의 각 기관의 구조를 관찰하고, 기능을 알아보는 실험을 수행하여 식물 각 기관의 구조와 기능을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과11-03', '과학', '초5~6', '식물의 구조와 기능', '여러 가지 식물의 특징을 설명하는 자료를 만들어 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과12-01', '과학', '초5~6', '지구의 운동', '하루 동안 태양과 별을 관찰하여 위치 변화의 규칙성을 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과12-02', '과학', '초5~6', '지구의 운동', '지구의 자전을 알고, 낮과 밤이 생기는 이유를 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과12-03', '과학', '초5~6', '지구의 운동', '지구의 공전을 알고, 계절에 따라 달라지는 별자리를 관찰할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과13-01', '과학', '초5~6', '계절의 변화', '태양 고도 측정기로 하루 동안 태양 고도, 그림자 길이, 기온을 측정하여 이들의 관계를 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과13-02', '과학', '초5~6', '계절의 변화', '계절에 따른 태양의 남중 고도와 낮의 길이 사이의 관계를 자료에 근거하여 추론할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과13-03', '과학', '초5~6', '계절의 변화', '계절 변화의 원인을 지구의 자전축이 기울어진 채 공전하는 것으로 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과14-01', '과학', '초5~6', '물질의 연소', '물질의 성질이 달라지는 변화와 달라지지 않는 변화를 관찰하여 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과14-02', '과학', '초5~6', '물질의 연소', '물질이 연소할 때 나타나는 공통적인 현상을 관찰하고, 연소의 조건을 찾을 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과14-03', '과학', '초5~6', '물질의 연소', '연소 전과 후의 물질을 비교하여 연소 과정에서 물질의 성질이 달라짐을 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과14-04', '과학', '초5~6', '물질의 연소', '연소 과정에서 생성되는 물질로 인한 생태계의 피해 사례를 수집하고 분석하여 해결책을 제안하고 공유할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과15-01', '과학', '초5~6', '전기의 이용', '전지와 전구, 전선을 연결하여 전구에 불을 켜보고, 불이 켜지는 전기 회로의 특징을 말할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과15-02', '과학', '초5~6', '전기의 이용', '전지 한 개를 연결한 전기 회로와 전지 두 개를 직렬연결한 전기 회로의 특징을 비교할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과15-03', '과학', '초5~6', '전기의 이용', '전자석을 만들어 전자석의 성질을 탐색하고 전자석이 사용되는 예를 조사할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과15-04', '과학', '초5~6', '전기의 이용', '전기를 효율적이고 안전하게 사용하는 방법을 조사하여 실천 계획을 세우고 일상생활에서 실천할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과16-01', '과학', '초5~6', '과학과 나의 진로', '미래 사회에 일어날 수 있는 문제를 조사하고, 문제를 해결하는 데 과학이 기여할 수 있는 방법을 토의할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6과16-02', '과학', '초5~6', '과학과 나의 진로', '다양한 진로가 과학과 관련됨을 알고, 자신의 진로를 과학과 관련지어 설명할 수 있다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도01-01', '도덕', '초5~6', '자신과의 관계', '자주적인 삶에 대한 이해를 바탕으로 자신의 생활계획을 세우고 실천하여 주체적인 삶의 태도를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도01-02', '도덕', '초5~6', '자신과의 관계', '생활 습관에 대한 성찰을 통해 자기 생활을 점검하고 올바른 계획을 세워 이를 실천한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도01-03', '도덕', '초5~6', '자신과의 관계', '자기가 하고 싶은 일을 선택할 때 도덕적 고려의 필요성을 알고 자신의 특기와 적성을 탐색하여 진로계획을 수립한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도02-01', '도덕', '초5~6', '타인과의 관계', '봉사의 의미와 중요성을 이해하고, 타인이 처한 상황과 환경에 대한 주의 깊은 관심을 바탕으로 봉사를 실천한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도02-02', '도덕', '초5~6', '타인과의 관계', '편견이 발생하는 이유를 탐색하여 해결 방안을 살펴보고, 다양성 존중을 바탕으로 다른 사람과 올바른 관계를 맺기 위한 실천 방안을 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도02-03', '도덕', '초5~6', '타인과의 관계', '인간과 인공지능 로봇 간의 다양한 관계를 파악하고 도덕에 기반을 둔 관계 형성의 필요성을 탐구한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도03-01', '도덕', '초5~6', '사회⋅공동체와의 관계', '인권과 관련된 다양한 사례를 살펴보고 인권에 관한 감수성을 길러 이를 실천하려는 의지를 함양한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도03-02', '도덕', '초5~6', '사회⋅공동체와의 관계', '정의에 관한 관심을 토대로 공동체 규칙의 중요성을 살펴보고 직접 공정한 규칙을 고안하며 기초적인 시민의식을 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도03-03', '도덕', '초5~6', '사회⋅공동체와의 관계', '통일과정과 통일 이후 사회의 여러 가지 상황을 예상하고 바람직한 통일과정과 통일 국가의 사회상을 제시한다', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도03-04', '도덕', '초5~6', '사회⋅공동체와의 관계', '다른 나라 사람들이 처한 여러 가지 상황을 종합적으로 이해하고 해결 방안을 탐구하며 인류애를 기른다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('6도04-01', '도덕', '초5~6', '자연과의 관계', '지구의 환경 위기 상황을 이해하고, 이를 극복하기 위한 다양한 방안을 찾아 자신의 일상에서 실천하고자 노력한다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 지구의 환경 위기 상황을 이해하고, 이를 극복하기 위한 다양한 방법을 찾아 자신의 일상에서 실천하고자 노력한다.'),
('6도04-02', '도덕', '초5~6', '자연과의 관계', '지속가능한 삶의 의미를 탐구하고 미래 세대에 대한 책임을 강화하여 자연의 다양성을 존중하고 생산성을 유지할 수 있는 미래를 위한 실천 방안을 찾는다.', 3, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-01', '국어', '중1~3', '듣기⋅말하기', '화자의 의도와 관점을 추론하며 듣는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-02', '국어', '중1~3', '듣기⋅말하기', '설득 전략을 비판적으로 분석하며 듣는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-03', '국어', '중1~3', '듣기⋅말하기', '담화 공동체에 따른 듣기⋅말하기 방식의 다양성을 고려하여 듣고 말한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-04', '국어', '중1~3', '듣기⋅말하기', '상대의 말을 경청하고 상대의 감정과 입장에 공감하는 반응을 보이며 대화한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9국01-05', '국어', '중1~3', '듣기⋅말하기', '면담의 다양한 목적과 상대를 고려하여 질문을 점검하고 효과적으로 면담한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-06', '국어', '중1~3', '듣기⋅말하기', '다양한 자료를 재구성하여 내용을 체계적으로 조직하고 청중이 이해하기 쉽게 발표한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-07', '국어', '중1~3', '듣기⋅말하기', '토의에서 다양한 의견을 교환하여 대안을 마련하고 문제를 해결한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-08', '국어', '중1~3', '듣기⋅말하기', '토론에서 반론을 고려하여 타당한 논증을 구성하고 논리적으로 반박한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-09', '국어', '중1~3', '듣기⋅말하기', '서로의 감정이나 바라는 바를 진솔하게 표현하면서 갈등을 조정한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국01-10', '국어', '중1~3', '듣기⋅말하기', '언어폭력의 문제점을 성찰하고, 서로를 존중하는 표현을 사용하여 말한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9국01-11', '국어', '중1~3', '듣기⋅말하기', '듣기⋅말하기 과정을 점검하고 듣기⋅말하기의 어려움을 효과적으로 조정한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-01', '국어', '중1~3', '읽기', '읽기는 사회⋅문화적 맥락에서 의미를 구성하는 과정임을 이해하며 사회적 독서에 참여하고 사회적 독서 문화 형성에 기여한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9국02-02', '국어', '중1~3', '읽기', '읽기 목적과 글의 구조를 고려하며 글을 효과적으로 요약한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-03', '국어', '중1~3', '읽기', '독자의 배경지식과 글에 나타난 정보 등을 활용하여 글에 드러나지 않은 의도나 관점을 추론하며 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-04', '국어', '중1~3', '읽기', '복합양식으로 구성된 글이나 자료의 내용 타당성과 신뢰성, 표현 방법의 적절성을 평가하며 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-05', '국어', '중1~3', '읽기', '글에 사용된 다양한 설명 방법과 논증 방법을 파악하고, 그 타당성을 평가하며 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-06', '국어', '중1~3', '읽기', '동일한 화제를 다룬 여러 글이나 자료를 주제 통합적으로 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국02-07', '국어', '중1~3', '읽기', '진로나 관심 분야에 대한 다양한 책이나 자료를 스스로 찾아 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9국02-08', '국어', '중1~3', '읽기', '자신의 독서 상황과 수준에 맞는 글을 선정하고 읽기 과정을 점검⋅조정하며 읽는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-01', '국어', '중1~3', '쓰기', '대상의 특성에 적합한 설명 방법을 활용하여 글을 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-02', '국어', '중1~3', '쓰기', '복수의 자료를 활용하여 다양한 형식으로 정보를 전달하는 글을 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-03', '국어', '중1~3', '쓰기', '주장을 뒷받침할 수 있는 타당한 근거를 들고 적절한 표현을 사용하여 주장하는 글을 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
