('9국03-05', '국어', '중1~3', '쓰기', '자신의 삶과 경험을 바탕으로 정서를 진솔하게 표현하는 글을 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-06', '국어', '중1~3', '쓰기', '다양한 표현을 활용하여 자신의 생각과 느낌이 드러나는 글을 쓰고 독자와 공유한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-07', '국어', '중1~3', '쓰기', '복합양식 자료를 활용하여 내용을 생성하고 글의 유형을 고려하여 내용을 조직하며 글을 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-08', '국어', '중1~3', '쓰기', '쓰기 과정과 전략을 점검⋅조정하며 글을 쓰고, 독자를 고려하여 글을 고쳐 쓴다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9국03-09', '국어', '중1~3', '쓰기', '언어 공동체의 구성원인 필자로서 자신에 대해 성찰하며, 윤리적 소통 문화를 형성하는 데에 기여한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
