('9수04-06', '수학', '중1~3', '자료와 가능성', '확률의 개념과 그 기본 성질을 이해하고, 확률을 구할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9수04-07', '수학', '중1~3', '자료와 가능성', '분산과 표준편차를 구하고 자료의 분포를 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9수04-08', '수학', '중1~3', '자료와 가능성', '공학 도구를 이용하여 자료를 상자그림으로 나타내고 분포를 비교할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9수04-09', '수학', '중1~3', '자료와 가능성', '자료를 산점도로 나타내고 상관관계를 말할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9사(일사)01-01', '사회', '중1~3', '인간과 사회생활', '사회화의 의미를 일상생활의 사례를 들어 설명하고, 사회화 과정에서 형성되는 자아 정체성에 대해 성찰한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)01-02', '사회', '중1~3', '인간과 사회생활', '사회적 지위와 역할의 의미를 설명하고, 일상생활에서 나타나는 역할 갈등 사례와 대응 방안을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)01-03', '사회', '중1~3', '인간과 사회생활', '우리 사회에 나타나는 다양한 갈등과 차별의 사례를 조사하고, 이에 대처하는 시민의 자질에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 우리 사회에서 나타나는 다양한 갈등과 차별의 사례를 조사하고, 이에 대처하는 시민의 자질에 대해 토의한다.'),
('9사(일사)02-01', '사회', '중1~3', '다양한 문화의 이해', '일상생활에서 접하는 문화의 사례를 탐색하고, 이를 바탕으로 문화의 의미와 특징을 도출한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)02-02', '사회', '중1~3', '다양한 문화의 이해', '우리 주변에서 활용되는 미디어들을 탐색하고, 미디어를 통해 경험하는 다양한 문화와 정보들을 비판적으로 검토한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)02-03', '사회', '중1~3', '다양한 문화의 이해', '여러 집단에서 나타나는 다양한 문화 사례들을 조사하고, 문화를 이해하는 바람직한 태도에 대하여 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)03-01', '사회', '중1~3', '민주주의와 시민', '공동체 생활에 필요한 정치의 역할을 탐색하고, 다양한 정치 사례를 통해 민주주의의 의미와 필요성을 도출한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)03-02', '사회', '중1~3', '민주주의와 시민', '민주주의의 발전 과정을 검토하고, 이를 토대로 민주주의의 이념과 기본 원리를 도출한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)03-03', '사회', '중1~3', '민주주의와 시민', '현대 민주주의의 특징과 과제를 검토하고, 우리나라 민주주의의 발전을 위한 제도적 방안과 시민의 역할에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)04-01', '사회', '중1~3', '정치과정과 시민 참여', '선거의 기능과 기본 원칙을 검토하고, 선거 과정에서 유권자와 정당이 수행하는 활동을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)04-02', '사회', '중1~3', '정치과정과 시민 참여', '정치활동에 참여하는 다양한 정치 주체의 역할을 탐색하고, 정치과정의 의미를 설명한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)04-03', '사회', '중1~3', '정치과정과 시민 참여', '민주주의의 발전을 위한 지방 자치의 중요성을 설명하고, 지역사회의 문제를 해결하기 위한 시민 참여 활동을 계획한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)05-01', '사회', '중1~3', '일상생활과 법', '법의 의미와 특징을 설명하고, 일상생활에서 접하는 법의 사례를 통해 법의 목적을 도출한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)05-02', '사회', '중1~3', '일상생활과 법', '우리의 일상을 규율하는 다양한 법을 탐색하고, 국내외 사례를 통해 사회법이 필요한 이유에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)05-03', '사회', '중1~3', '일상생활과 법', '재판의 의미와 종류를 설명하고, 공정한 재판의 중요성에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)06-01', '사회', '중1~3', '인권과 기본권', '일상생활에서 인권이 침해되는 사례를 조사하고, 우리 헌법에 보장된 기본권의 종류를 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)06-02', '사회', '중1~3', '인권과 기본권', '기본권 제한의 요건과 한계가 헌법에 명시된 이유를 토의하고, 기본권 침해 시 구제 방법을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)06-03', '사회', '중1~3', '인권과 기본권', '근로자에게 보장되는 권리를 조사하고, 이러한 권리의 침해에 대처하는 국가와 시민의 노력에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)07-01', '사회', '중1~3', '헌법과 국가기관', '우리나라의 정부 형태를 설명하고, 대통령과 행정부의 역할을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)07-02', '사회', '중1~3', '헌법과 국가기관', '국회에서 법률이 만들어지는 사례를 탐색하고, 입법기관으로서 국회의 역할을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)07-03', '사회', '중1~3', '헌법과 국가기관', '사법기관으로서 법원의 역할을 검토하고, 헌법재판소의 성격에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)08-01', '사회', '중1~3', '경제생활과 선택', '경제생활에서 합리적 선택의 필요성에 대해 검토하고, 비용과 편익을 고려한 합리적 선택 방안을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)08-02', '사회', '중1~3', '경제생활과 선택', '일생 동안 이루어지는 경제생활을 분석하고, 안정적인 금융 생활을 위한 자산 및 신용 관리 방안을 계획한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)08-03', '사회', '중1~3', '경제생활과 선택', '시장경제에서 기업의 역할과 사회적 책임을 설명하고, 우리 사회에 필요한 기업가 정신에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)09-01', '사회', '중1~3', '시장과 가격', '일상생활에서 접하는 다양한 시장의 사례를 조사하고, 이를 토대로 시장의 의미와 필요성을 설명한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)09-02', '사회', '중1~3', '시장과 가격', '수요 법칙과 공급 법칙을 사례를 통해 도출하고, 이를 토대로 시장 가격이 결정되는 원리를 설명한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)09-03', '사회', '중1~3', '시장과 가격', '시장경제에서 수요와 공급을 변화시키는 요인을 조사하고, 시장 가격의 변동에 대응하는 방안을 계획한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)10-01', '사회', '중1~3', '우리나라 경제와 세계화', '우리나라의 경제 성장 전후 모습을 검토하고, 국내 총생산의 증가가 우리 생활에 미치는 영향에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)10-02', '사회', '중1~3', '우리나라 경제와 세계화', '물가 변동과 실업의 사례를 탐색하고 물가 변동과 실업이 우리 생활에 미치는 영향을 제시한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)10-03', '사회', '중1~3', '우리나라 경제와 세계화', '세계화 시대에 국제 거래가 이루어지는 사례를 탐색하고, 환율 변동이 우리 생활에 미치는 영향을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)11-01', '사회', '중1~3', '국제 사회와 한반도', '국제 사회를 구성하는 여러 행위 주체의 활동을 조사하고, 이를 토대로 국제 사회의 특징을 도출한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)11-02', '사회', '중1~3', '국제 사회와 한반도', '국제 사회의 다양한 분쟁에 대해 조사하고, 지역, 국가, 세계의 시민으로서 우리의 역할에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)11-03', '사회', '중1~3', '국제 사회와 한반도', '우리나라가 직면하고 있는 국제 문제에 대해 조사하고, 이러한 문제에 대응하기 위한 방안에 대해 토론한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', '성취수준 자료의 문구: 우리나라가 직면하고 있는 국제 문제에 대해 조사하고, 해당 문제에 대응하기 위한 방안에 대해 토론한다.'),
('9사(일사)12-01', '사회', '중1~3', '사회 변동과 사회문제', '오늘날 우리 사회가 겪는 사회 변동에 대해 조사하고, 이러한 사회 변동이 우리 생활에 미치는 영향을 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)12-02', '사회', '중1~3', '사회 변동과 사회문제', '오늘날의 주요한 사회문제를 조사하고, 이러한 사회문제가 우리 생활에 미치는 영향에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(일사)12-03', '사회', '중1~3', '사회 변동과 사회문제', '사회 변동과 사회문제에 대응하는 국내외의 사례들을 검토하고, 시민으로서 지녀야 할 태도와 실천 방안에 대해 토의한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)01-01', '사회', '중1~3', '세계화 시대, 지리의 힘', '세계 여러 지역의 특성을 해당 지역의 위치와 자연⋅인문환경을 고려하여 추론한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)01-02', '사회', '중1~3', '세계화 시대, 지리의 힘', '다양한 스케일에서 지역이 서로 연계되어 있음을 공간적 상호 작용의 사례를 통해 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)01-03', '사회', '중1~3', '세계화 시대, 지리의 힘', '세계의 변화가 지역에 영향을 미치고 지역의 변화가 세계에 영향을 미치는 사례를 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)02-01', '사회', '중1~3', '아시아', '다양한 지리 정보와 매체를 활용하여 아시아의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)02-02', '사회', '중1~3', '아시아', '종교와 관련된 아시아의 다양한 문화경관과 생활양식을 파악하고, 세계시민으로서 문화 다양성에 대한 이해와 수용성을 높인다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)02-03', '사회', '중1~3', '아시아', '아시아의 인구 특징을 파악하고 지역별 인구 구조 변화를 비교하여 지역 발전의 가능성 및 변화 모습을 추론한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)02-04', '사회', '중1~3', '아시아', '글로컬 관점에서 아시아의 산업 특징과 변화를 파악하고, 이것이 우리나라 산업에 미치는 영향을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)03-01', '사회', '중1~3', '유럽', '다양한 지리 정보와 매체를 활용하여 유럽의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)03-02', '사회', '중1~3', '유럽', '다양한 유형의 유럽 도시를 탐색하고, 기후위기에 대응하여 지속가능한 도시를 만들기 위한 노력을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)03-03', '사회', '중1~3', '유럽', '지역 간 역학관계에 따른 유럽의 통합과 분리의 움직임이 유럽연합의 변화와 주민 생활에 미치는 영향을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)04-01', '사회', '중1~3', '아프리카', '다양한 지리 정보와 매체를 활용하여 아프리카의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)04-02', '사회', '중1~3', '아프리카', '아프리카의 지리적 특성에 기반한 다양한 문화와 지역 잠재력을 탐구하고, 아프리카에 대한 자신의 인식을 성찰한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)04-03', '사회', '중1~3', '아프리카', '지속가능한 발전을 위한 아프리카 각 지역의 노력과 세계 다양한 주체들의 협력 사례를 조사하고, 세계시민으로서 우리가 참여할 수 있는 방안을 모색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)05-01', '사회', '중1~3', '아메리카', '다양한 지리 정보와 매체를 활용하여 아메리카의 국가와 주요 도시의 위치를 파악하고 자연환경의 특성을 지도로 표현한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)05-02', '사회', '중1~3', '아메리카', '다양한 민족(인종)으로 구성된 아메리카의 인구 특징을 살펴보고, 사례를 들어 아메리카의 문화 혼종성을 설명한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)05-03', '사회', '중1~3', '아메리카', '초국적 기업의 글로벌 생산체제에 대한 이해를 바탕으로, 초국적 기업의 아메리카 지역 내 입지와 해외 이전의 이유, 그에 따른 해당 지역의 변화를 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)06-01', '사회', '중1~3', '오세아니아와 극지방', '다양한 지리 정보와 매체를 활용하여 오세아니아의 국가와 주요 도시의 위치, 자연환경의 특성을 파악하고, 자원 수출을 중심으로 세계 다른 지역과의 상호연계성을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)06-02', '사회', '중1~3', '오세아니아와 극지방', '태평양 지역이 겪고 있는 환경 문제를 조사하고 그 해결에 참여할 수 있는 방안을 제안한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)06-03', '사회', '중1~3', '오세아니아와 극지방', '극지방의 지리적 중요성과 지역 개발을 둘러싼 다양한 이해관계를 살펴보고, 이에 대한 자신과 상대방의 의견을 비판적으로 검토한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)07-01', '사회', '중1~3', '대한민국, 우리가 살아가는 곳', '우리 국토의 위치와 영역에 대한 이해를 바탕으로 세계 속에서 우리나라의 위치를 지정학, 지경학적 측면에서 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)07-02', '사회', '중1~3', '대한민국, 우리가 살아가는 곳', '우리나라 행정구역과 주요 도시의 위치를 파악하고, 자신이 살고 있는 곳의 장소성과 장소감을 표현한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)07-03', '사회', '중1~3', '대한민국, 우리가 살아가는 곳', '다양한 지리 정보와 매체를 활용하여 우리 지역의 문제를 선정하고 지리적으로 시각화한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)08-01', '사회', '중1~3', '우리나라의 자연환경과 인간 생활', '우리나라 주요 산지⋅하천⋅해안 지형의 위치와 특성을 파악하고, 매력적인 지형 경관을 탐색하여 우리 국토의 아름다움을 느낀다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)08-02', '사회', '중1~3', '우리나라의 자연환경과 인간 생활', '우리나라의 계절별, 지역별 기후 특성 및 변화 양상을 파악하고, 기후변화에 대한 지역별 대응 노력을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)08-03', '사회', '중1~3', '우리나라의 자연환경과 인간 생활', '우리나라 자연재해의 지리적 특성과 피해 최소화를 위한 노력을 파악하고, 일상생활 속 다양한 상황에서 자연재해 발생 시 자신의 대처 방안을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)09-01', '사회', '중1~3', '중부 지역', '다양한 지리 정보와 매체를 활용하여 중부 지역의 지리적 특성 및 매력적인 여행 장소들을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)09-02', '사회', '중1~3', '중부 지역', '수도권의 공간 구조를 파악하고, 인구⋅문화⋅경제적 측면을 중심으로 수도권의 변화 양상을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)09-03', '사회', '중1~3', '중부 지역', '강원⋅충청 지역의 변화를 교통 발달과 수도권과의 관계를 중심으로 파악하고, 강원⋅충청 지역의 산업 변화와 지역경제 활성화를 위한 노력을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)09-04', '사회', '중1~3', '중부 지역', '수도권과 비수도권 간의 지역 불균형 실태를 지도로 표현하고, 지역 불균형을 완화하기 위한 방안들을 제안한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)10-01', '사회', '중1~3', '남부 지역', '다양한 지리 정보와 매체를 활용하여 남부 지역의 지리적 특성 및 매력적인 여행 장소들을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)10-02', '사회', '중1~3', '남부 지역', '글로벌 경제와 우리나라 산업에서 영⋅호남 공업 지역의 위상을 파악하고, 영⋅호남 지역의 산업 변화와 당면 과제를 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)10-03', '사회', '중1~3', '남부 지역', '제주도의 지역 변화와 이를 둘러싼 다양한 가치를 살펴보고 이에 대한 자신과 상대방의 의견을 비판적으로 검토한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)11-01', '사회', '중1~3', '북부 지역', '다양한 지리 정보와 매체를 활용하여 북한의 자연환경과 인문환경의 특징을 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)11-02', '사회', '중1~3', '북부 지역', '분단이 우리의 일상생활에 미친 영향을 살펴보고, 분리와 연결의 공간으로서 접경지역의 다양한 모습을 세계 여러 지역의 사례를 통해 비교한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)11-03', '사회', '중1~3', '북부 지역', '세계시민의 관점에서 한반도 평화의 중요성을 논의하고, 한반도 평화와 통일 환경 속에서 우리의 삶과 국토의 미래를 구상한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)12-01', '사회', '중1~3', '지속가능한 세계와 글로컬 시민', '우리나라 주요 식량 자원 및 에너지 자원의 소비 현황과 수입국 현황을 분석하여 이와 관련된 문제를 파악하고, 자원의 지속가능한 확보 방안을 모색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)12-02', '사회', '중1~3', '지속가능한 세계와 글로컬 시민', '지역 개발과 환경 보존을 둘러싼 글로컬 환경 이슈에 관심을 가지고 자신의 웰빙 및 공동체의 지속가능한 발전을 위해 참여하고 실천한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9사(지리)12-03', '사회', '중1~3', '지속가능한 세계와 글로컬 시민', '더 나은 지역을 만들어 가는 사람들의 노력을 국내외 사례를 통해 살펴보고, 자신이 사는 지역의 문제를 해결하기 위한 방안을 모색하고 이를 실천한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역01-01', '사회', '중1~3', '역사 학습의 기초', '역사와 역사 탐구의 의미를 파악하고, 역사 학습의 목적을 다각도로 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역01-02', '사회', '중1~3', '역사 학습의 기초', '다양한 자료와 사례를 통해 역사 탐구 방법을 익힌다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역02-01', '사회', '중1~3', '문명의 발생과 고대 세계의 형성', '선사 문화 및 문명의 형성을 이해하고, 각 문명의 특징을 비교한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역02-02', '사회', '중1~3', '문명의 발생과 고대 세계의 형성', '서아시아⋅지중해 세계에서 등장한 여러 정치체를 비교하고 종교 및 문화를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역02-03', '사회', '중1~3', '문명의 발생과 고대 세계의 형성', '중국과 인도의 정치적 변화와 종교⋅사상 성립의 관계를 이해하고, 유라시아의 상호 교류를 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역03-01', '사회', '중1~3', '세계 종교의 확산과 지역 문화의 발전', '수⋅당 시기 동아시아 국제 질서의 특징을 이해하고, 동아시아 문화를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역03-02', '사회', '중1~3', '세계 종교의 확산과 지역 문화의 발전', '인도, 서아시아, 지중해에서 진행된 정치적 변동 과정과 각 종교의 특징 및 영향을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역03-03', '사회', '중1~3', '세계 종교의 확산과 지역 문화의 발전', '크리스트교 세계의 정치와 종교의 상관성을 이해하고, 이슬람 세계와 크리스트교 세계의 충돌 및 교류의 결과를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역04-01', '사회', '중1~3', '지역 세계의 교류와 변화', '송과 몽골 제국 시기 유라시아⋅인도양 교역권의 성장을 경제⋅문화 자료를 통해 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역04-02', '사회', '중1~3', '지역 세계의 교류와 변화', '명⋅청, 에도 막부, 무굴 제국의 정치⋅사회 변화를 비교한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역04-03', '사회', '중1~3', '지역 세계의 교류와 변화', '오스만 제국의 성장과 유럽 사회의 근대적 변화를 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역05-01', '사회', '중1~3', '제국주의와 국민 국가 건설 운동', '시민 혁명을 국민 국가 형성과 연결하여 파악하고, 역사적 의의와 한계를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역05-02', '사회', '중1~3', '제국주의와 국민 국가 건설 운동', '서양의 산업화와 제국주의 정책을 이해하고, 사회와 생태환경에 미친 영향을 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역05-03', '사회', '중1~3', '제국주의와 국민 국가 건설 운동', '제국주의 열강의 침략에 대한 아시아의 대응 및 국민 국가 건설 노력을 이해하고, 그 성과와 한계를 평가한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역06-01', '사회', '중1~3', '세계 대전과 사회 변동', '20세기 전반 세계 질서의 변화를 두 차례의 세계 대전을 중심으로 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역06-02', '사회', '중1~3', '세계 대전과 사회 변동', '세계 대전 중의 전쟁 범죄를 탐구하고, 인권 회복과 평화 실현을 위한 노력을 조사한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역06-03', '사회', '중1~3', '세계 대전과 사회 변동', '아시아⋅아프리카 지역의 민족 운동을 이해하고, 그 특징을 비교한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역07-01', '사회', '중1~3', '현대 세계의 전개와 과제', '냉전의 전개와 제3 세계 등장의 상관관계를 이해하고, 냉전 이후 국제 질서의 변화를 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역07-02', '사회', '중1~3', '현대 세계의 전개와 과제', '20세기 후반 민주주의와 인권의 신장을 위한 노력에 관심을 갖는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역07-03', '사회', '중1~3', '현대 세계의 전개와 과제', '오늘날 세계화의 양상을 조사하고, 성과와 과제를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역08-01', '사회', '중1~3', '국가의 형성과 발전', '고조선과 여러 나라의 형성 과정 및 사회 모습을 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역08-02', '사회', '중1~3', '국가의 형성과 발전', '삼국과 가야의 성장 과정을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역08-03', '사회', '중1~3', '국가의 형성과 발전', '삼국과 가야가 남긴 문화의 특징을 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역09-01', '사회', '중1~3', '통일신라와 발해', '삼국 통일의 과정을 동아시아 국제 정세의 맥락에서 이해하고, 통일신라와 발해 성립의 역사적 의의를 추론한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역09-02', '사회', '중1~3', '통일신라와 발해', '통일신라와 발해의 국가 체제 정비와 변동을 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역09-03', '사회', '중1~3', '통일신라와 발해', '통일신라와 발해 문화의 특징을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역10-01', '사회', '중1~3', '고려의 성립과 변천', '후삼국 통일과 체제 정비 과정을 통해 고려 성립의 역사적 의미를 탐색한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역10-02', '사회', '중1~3', '고려의 성립과 변천', '고려의 정치적 변동을 파악하고 주변국과의 관계를 이해한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역10-03', '사회', '중1~3', '고려의 성립과 변천', '원 간섭기 고려 사회에 나타난 변화를 파악하고 개혁의 영향을 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역10-04', '사회', '중1~3', '고려의 성립과 변천', '고려의 문화유산과 대외 교류의 사례를 조사하여 그 특징을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역11-01', '사회', '중1~3', '조선의 성립과 발전', '조선 성립의 의의를 통치 체제의 특징을 통해 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역11-02', '사회', '중1~3', '조선의 성립과 발전', '사림 세력의 성장이 성리학적 질서 확산에 끼친 영향을 추론한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역11-03', '사회', '중1~3', '조선의 성립과 발전', '왜란과 호란의 성격을 동아시아 국제 정세 속에서 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역12-01', '사회', '중1~3', '조선 사회의 변동', '왜란과 호란 이후 체제 재정비의 노력과 정치 변동의 모습을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역12-02', '사회', '중1~3', '조선 사회의 변동', '조선 후기 문화에서 나타난 변화를 분석한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역12-03', '사회', '중1~3', '조선 사회의 변동', '조선 후기 사회적 모순에 대한 여러 세력의 대응을 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역13-01', '사회', '중1~3', '근⋅현대 사회로의 전환', '개항 이후 근대 국가를 건설하기 위한 노력을 파악한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역13-02', '사회', '중1~3', '근⋅현대 사회로의 전환', '국권 피탈 이후 전개된 민족 운동을 세계사적 관점에서 이해한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역13-03', '사회', '중1~3', '근⋅현대 사회로의 전환', '한국의 민주화 과정에서 나타난 성과와 과제를 탐구한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9역13-04', '사회', '중1~3', '근⋅현대 사회로의 전환', '지속가능한 사회를 위한 과제를 역사적 맥락에서 탐구하고, 과제 해결에 참여하는 자세를 갖는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과01-01', '과학', '중1~3', '과학과 인류의 지속가능한 삶', '과학적 탐구 방법을 이해하고, 일상생활의 문제에 대한 과학적 해결 방안을 제안할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과01-02', '과학', '중1~3', '과학과 인류의 지속가능한 삶', '과학의 발전이 인류 문명에 미친 영향을 이해하고, 인공지능 등 첨단 과학기술이 가져올 미래 사회의 변화를 조사하여 발표할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과01-03', '과학', '중1~3', '과학과 인류의 지속가능한 삶', '인류의 지속가능한 삶을 위한 과학기술의 중요성과 역할에 대해 토의하고, 개인과 사회 차원의 활동 방안을 찾아 실천할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과02-01', '과학', '중1~3', '생물의 구성과 다양성', '세포는 생명 활동이 일어나는 기본 단위임을 이해하고, 세포의 구조와 기능의 관계를 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과02-02', '과학', '중1~3', '생물의 구성과 다양성', '생물의 유기적 구성 단계를 이해하고, 동물과 식물을 비교하여 분석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과02-03', '과학', '중1~3', '생물의 구성과 다양성', '생물다양성을 이해하고, 변이와 생물다양성의 관계를 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과02-04', '과학', '중1~3', '생물의 구성과 다양성', '종의 개념과 분류 체계를 이해하고, 생물을 계 수준에서 분류할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과02-05', '과학', '중1~3', '생물의 구성과 다양성', '생물다양성 보전의 필요성을 이해하고, 생물다양성 유지를 위한 방안을 조사하고 실천할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과03-01', '과학', '중1~3', '열', '온도와 열평형 과정을 물질을 구성하는 입자들의 배치나 움직임 등으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과03-02', '과학', '중1~3', '열', '열은 전도, 대류, 복사로 전달됨을 알고, 열전달 과정을 모형 등을 사용하여 다양하게 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과03-03', '과학', '중1~3', '열', '물질에 따라 비열과 열팽창 정도가 다름을 알고, 이러한 성질이 일상생활에서 유용하게 활용됨을 인식할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과04-01', '과학', '중1~3', '물질의 상태 변화', '확산 및 증발 현상을 관찰하여 물질을 구성하는 입자가 운동하고 있음을 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과04-02', '과학', '중1~3', '물질의 상태 변화', '물질의 세 가지 상태의 특징을 설명하고, 이를 입자 모형으로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과04-03', '과학', '중1~3', '물질의 상태 변화', '여러 가지 물질의 상태 변화를 관찰하고, 이를 입자 모형으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과04-04', '과학', '중1~3', '물질의 상태 변화', '물질의 상태 변화와 열에너지 출입 관계를 이해하고, 이를 실생활에 적용하여 과학의 유용성을 인식할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과05-01', '과학', '중1~3', '힘의 작용', '물체에 작용하는 힘을 화살표를 이용하여 나타내고, 힘의 평형을 이루는 조건을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과05-02', '과학', '중1~3', '힘의 작용', '중력, 탄성력, 마찰력, 부력을 이해하고, 각 힘의 특징을 크기와 방향으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과05-03', '과학', '중1~3', '힘의 작용', '알짜힘이 0이 아닐 때 물체의 운동 상태가 변함을 알고, 그 예를 조사하여 분류할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과05-04', '과학', '중1~3', '힘의 작용', '다양한 사례에서 작용하는 힘과 힘의 평형 관계를 설명하고, 일상생활에서 힘의 특징을 이용한 기구나 장치를 설계할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과06-01', '과학', '중1~3', '기체의 성질', '압력의 의미를 알고, 기체의 압력을 입자의 운동으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과06-02', '과학', '중1~3', '기체의 성질', '기체의 압력과 부피 관계를 실험 결과로부터 알아내고, 이를 입자 모형으로 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과06-03', '과학', '중1~3', '기체의 성질', '기체의 온도와 부피 관계를 실험 결과로부터 알아내고, 이를 입자 모형으로 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과07-01', '과학', '중1~3', '태양계', '태양계를 구성하는 천체의 특징을 알고, 행성을 목성형 행성과 지구형 행성으로 구분할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과07-02', '과학', '중1~3', '태양계', '태양의 표면과 대기에서 일어나는 현상을 알고, 태양의 활동이 지구에 미치는 영향을 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과07-03', '과학', '중1~3', '태양계', '지구 자전에 의한 천체의 겉보기 운동과 지구 공전에 의한 별자리 변화를 이해하고, 밤하늘 천체에 호기심을 가진다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B 같은 기술(원자료 병합 칸)'),
('9과07-04', '과학', '중1~3', '태양계', '달을 관측하여 달의 위상변화 원리를 이해하고, 일식과 월식을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과08-01', '과학', '중1~3', '물질의 특성', '물질의 특성의 의미를 알고, 실험을 통해 밀도, 용해도, 녹는점, 끓는점 등을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B 같은 기술(원자료 병합 칸)'),
('9과08-02', '과학', '중1~3', '물질의 특성', '물질의 특성을 근거로 우리 주변의 물질을 순물질과 혼합물로 분류할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B 같은 기술(원자료 병합 칸)'),
('9과08-03', '과학', '중1~3', '물질의 특성', '물질의 특성을 이용하여 혼합물이 분리되는 원리를 이해하고, 이를 이용한 사례를 주변에서 찾을 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과09-01', '과학', '중1~3', '지권의 변화', '지구계의 구성 요소를 알고, 지권의 층상 구조와 그 특징을 조사⋅발표할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과09-02', '과학', '중1~3', '지권의 변화', '조암 광물의 주요 특성을 관찰하고, 암석과 광물의 활용 방안 및 자원으로서 가치에 대해 조사할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과09-03', '과학', '중1~3', '지권의 변화', '지각을 이루는 암석을 생성 과정에 따라 분류하고, 암석의 순환 과정을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과09-04', '과학', '중1~3', '지권의 변화', '풍화 과정을 이해하고, 토양 생성 과정을 풍화 작용의 예로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과09-05', '과학', '중1~3', '지권의 변화', '대륙이동설을 이해하고, 지진과 화산이 발생하는 지역의 분포를 판의 경계와 관련지어 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과10-01', '과학', '중1~3', '빛과 파동', '빛의 반사와 굴절의 원리를 이해하고, 물체를 보는 과정을 빛의 경로를 이용하여 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과10-02', '과학', '중1~3', '빛과 파동', '평면거울에서 상이 생기는 원리를 설명하고, 일상생활에서 사용되는 거울과 렌즈의 종류를 분류하고 상의 특징을 비교할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'B·C 같은 기술(원자료 병합 칸)'),
('9과10-03', '과학', '중1~3', '빛과 파동', '물체의 색을 빛의 반사와 관련지어 설명하고, 영상 장치에서 빛의 합성을 이용하여 다양한 색이 표현되는 원리를 이해할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과10-04', '과학', '중1~3', '빛과 파동', '파동의 발생과 전달 과정을 이해하고, 소리의 특성을 진폭, 진동수, 파형 등의 과학적 용어로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과11-01', '과학', '중1~3', '물질의 구성', '원소와 화합물의 정의를 알고, 원소와 화합물을 화학식으로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'B·C 같은 기술(원자료 병합 칸)'),
('9과11-02', '과학', '중1~3', '물질의 구성', '원소를 구성하는 입자인 원자는 양성자, 중성자, 전자로 구성되며, 양성자의 수에 따라 원소의 종류가 달라짐을 입자 모형을 활용하여 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'C·D 같은 기술(원자료 병합 칸)'),
('9과11-03', '과학', '중1~3', '물질의 구성', '원소는 양성자의 수에 따라 주기율표에 배치됨을 알고, 주기율표에서 성질이 유사한 원소를 찾을 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B 같은 기술(원자료 병합 칸)'),
('9과11-04', '과학', '중1~3', '물질의 구성', '물질을 이루는 입자는 원자, 분자, 이온 등으로 존재할 수 있음을 알고, 이온은 전하를 띠고 있음을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과12-01', '과학', '중1~3', '식물과 에너지', '광합성 과정을 이해하고, 환경 요인과 광합성의 관계를 탐구하는 실험을 설계할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과12-02', '과학', '중1~3', '식물과 에너지', '식물의 호흡과 광합성의 관계를 이해하고, 호흡과 광합성 과정에서 출입하는 에너지와 물질의 변화를 분석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과12-03', '과학', '중1~3', '식물과 에너지', '광합성 산물의 저장과 이용 과정을 이해하고, 모형으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과13-01', '과학', '중1~3', '동물과 에너지', '소화계의 구조와 기능을 이해하고, 소화 과정을 소화 효소의 작용과 관련지어 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과13-02', '과학', '중1~3', '동물과 에너지', '순환계의 구조와 기능을 이해하고, 혈액의 순환 경로를 종합하여 발표할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과13-03', '과학', '중1~3', '동물과 에너지', '호흡계의 구조와 기능을 이해하고, 호흡 운동의 원리를 나타내는 모형을 만들 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과13-04', '과학', '중1~3', '동물과 에너지', '배설계의 구조와 기능을 이해하고, 노폐물이 배설되는 과정을 모식도로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과13-05', '과학', '중1~3', '동물과 에너지', '동물이 세포호흡을 통해 에너지를 얻는 과정을 소화, 순환, 호흡, 배설과 관련지어 통합적으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과14-01', '과학', '중1~3', '전기와 자기', '마찰 전기, 정전기 유도 현상을 관찰하고, 이를 전기력과 원자 모형을 이용하여 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과14-02', '과학', '중1~3', '전기와 자기', '전기 회로에서 전류를 모형으로 설명하고, 실험을 통해 저항, 전류, 전압 사이의 관계를 이끌어낼 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과14-03', '과학', '중1~3', '전기와 자기', '저항의 직렬연결과 병렬연결의 특징을 비교하고, 일상생활에서 전기 에너지가 다양한 형태의 에너지로 전환됨을 소비 전력과 관련지어 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과14-04', '과학', '중1~3', '전기와 자기', '자기장 안에 놓인 전류가 흐르는 코일이 받는 힘의 특성을 추리하고, 전동기 등 일상생활에서 활용한 예를 찾을 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과15-01', '과학', '중1~3', '별과 우주', '연주시차를 이용하여 별까지의 거리를 구할 수 있고, 별의 등급과 밝기의 관계 및 표면 온도와 색의 관계를 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과15-02', '과학', '중1~3', '별과 우주', '우리은하의 구조와 크기를 이해하고, 성운과 성단의 특징을 비교할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과15-03', '과학', '중1~3', '별과 우주', '모형을 이용하여 우주가 팽창하고 있음을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과15-04', '과학', '중1~3', '별과 우주', '우주탐사의 의의와 인류에게 미치는 영향을 조사하여 과학의 유용성을 인식할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과16-01', '과학', '중1~3', '화학 반응의 규칙성', '물리 변화와 화학 변화의 의미를 알고, 화학 변화에서 새로운 물질이 생성됨을 관찰할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, D·E 같은 기술(원자료 병합 칸)'),
('9과16-02', '과학', '중1~3', '화학 반응의 규칙성', '간단한 화학 반응을 화학 반응식으로 표현하고, 화학 반응식에서 계수의 비를 입자 수의 비로 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과16-03', '과학', '중1~3', '화학 반응의 규칙성', '화학 반응에서 질량이 보존됨을 실험을 통해 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'C·D 같은 기술(원자료 병합 칸)'),
('9과16-04', '과학', '중1~3', '화학 반응의 규칙성', '화합물을 구성하는 성분 원소의 질량비가 일정함을 실험 자료를 해석하여 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과16-05', '과학', '중1~3', '화학 반응의 규칙성', '기체 반응에서 기체 부피 사이의 비가 일정함을 실험 자료를 해석하여 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'B·C 같은 기술(원자료 병합 칸)'),
('9과16-06', '과학', '중1~3', '화학 반응의 규칙성', '화학 반응에서 열에너지가 출입함을 알고, 생활 속 사례를 조사하여 발표할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과17-01', '과학', '중1~3', '날씨와 기후변화', '지구 대기권을 4개 권역으로 구분하며, 온실효과와 지구온난화를 복사 평형의 관점으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과17-02', '과학', '중1~3', '날씨와 기후변화', '대기 대순환에서 위도별 바람의 특성을 파악하고, 대기 대순환의 역할을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과17-03', '과학', '중1~3', '날씨와 기후변화', '상대습도, 단열 팽창 및 응결 현상의 관계를 이해하고, 구름의 생성과 강수 과정을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과17-04', '과학', '중1~3', '날씨와 기후변화', '기압, 기단, 전선의 개념을 이해하고, 일기도에서 저기압과 고기압의 분포에 따른 날씨를 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과18-01', '과학', '중1~3', '수권과 해수의 순환', '수권에서 해수, 담수, 빙하의 분포와 활용 사례를 조사하고, 자원으로서 물의 가치에 대해 토론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과18-02', '과학', '중1~3', '수권과 해수의 순환', '해수의 수온과 염분의 분포 및 변화를 해석하여 해수의 특성을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과18-03', '과학', '중1~3', '수권과 해수의 순환', '대기 대순환과 해양 표층 순환과의 관계를 이해하고, 기후변화에 영향을 미치는 해류의 역할을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과19-01', '과학', '중1~3', '운동과 에너지', '직선상에서 움직이는 물체의 운동을 그래프로 나타내고 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과19-02', '과학', '중1~3', '운동과 에너지', '자유 낙하하는 물체의 운동에서 시간에 따른 속력의 변화가 일정함을 분석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과19-03', '과학', '중1~3', '운동과 에너지', '일의 정의를 알고, 자유 낙하하는 물체의 운동에서 중력이 한 일을 위치 에너지와 운동 에너지로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과19-04', '과학', '중1~3', '운동과 에너지', '물체의 운동에서 역학적 에너지의 전환과 보존을 이해하고, 이를 활용하여 일상생활 속 물체의 운동을 예측할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과20-01', '과학', '중1~3', '자극과 반응', '감각기관의 구조와 기능을 이해하고, 실험을 통해 자극이 뇌로 전달되는 과정을 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과20-02', '과학', '중1~3', '자극과 반응', '뉴런과 신경계의 구조와 기능을 이해하고, 자극에서 반응이 일어나기까지의 과정을 모형으로 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과20-03', '과학', '중1~3', '자극과 반응', '우리 몸의 기능 조절에 호르몬이 관여함을 알고, 관련 자료를 조사하여 발표할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과21-01', '과학', '중1~3', '생식과 유전', '개체의 생장에 세포분열이 필요한 이유를 세포의 표면적과 부피의 관계로 추론할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'B·C 같은 기술(원자료 병합 칸)'),
('9과21-02', '과학', '중1~3', '생식과 유전', '염색체와 유전자의 관계를 이해하고, 체세포분열과 생식세포 형성과정의 특징을 염색체 행동을 중심으로 해석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과21-03', '과학', '중1~3', '생식과 유전', '수정란으로부터 개체가 발생하는 과정을 모형으로 표현할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과21-04', '과학', '중1~3', '생식과 유전', '멘델 유전 실험의 의의와 원리를 이해하고, 멘델 유전 원리가 적용되는 유전 현상을 조사하여 협력적으로 소통할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과21-05', '과학', '중1~3', '생식과 유전', '사람의 유전 형질과 유전 연구 방법을 알고, 가계도를 분석하여 사람의 유전 현상을 설명할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과22-01', '과학', '중1~3', '재해⋅재난과 안전', '재해⋅재난 사례와 관련된 자료를 조사하고, 그 발생 원인과 피해에 대해 과학적으로 분석할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과22-02', '과학', '중1~3', '재해⋅재난과 안전', '과학적 원리를 이용하여 재해⋅재난에 대한 대비 및 대처 방안을 세울 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', 'A·B, C·D 같은 기술(원자료 병합 칸)'),
('9과23-01', '과학', '중1~3', '과학과 나의 미래', '과학과 관련된 직업의 종류와 하는 일을 조사하고, 과학기술의 발달로 생기는 미래 사회의 직업 변화를 예상할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9과23-02', '과학', '중1~3', '과학과 나의 미래', '자신의 진로와 관련 있는 과학 분야를 조사하고, 진로 선택을 위하여 필요한 과학 학습을 계획할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-01', '도덕', '중1~3', '자신과의 관계', '자신의 삶과 가치관에 대한 성찰을 통해 자아를 올바로 이해하고, 삶에서 도덕이 필요한 이유에 근거하여 도덕적인 삶에 대한 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-02', '도덕', '중1~3', '자신과의 관계', '일상에서 발생하는 부도덕한 행동의 여러 원인을 분석하고, 도덕적 인격이 갖추어야 할 특성들을 파악하여 이를 내면화하는 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-03', '도덕', '중1~3', '자신과의 관계', '행복에 관한 심리적, 사회적, 윤리적 접근 등을 통해 행복의 의미를 종합적으로 파악하고, 삶의 목적과 행복의 관계를 정립할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-04', '도덕', '중1~3', '자신과의 관계', '옳고 그름을 분별할 수 있는 도덕적 기준을 탐구하고, 도덕적 상상력을 바탕으로 일상의 도덕 문제들에 도덕적 추론을 적용할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-05', '도덕', '중1~3', '자신과의 관계', '삶의 유한함에 관한 성찰을 통해 생명의 소중함과 의미 있는 삶의 중요성을 인식하고, 자신의 미래 모습을 상상하며 삶을 계획하고 이를 실천하는 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-06', '도덕', '중1~3', '자신과의 관계', '내면에 대한 성찰을 통해 심리적 고통과 불안, 우울감 등의 원인을 찾고, 마음의 평온을 얻을 수 있는 방안들을 다각적으로 모색하여 실천할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도01-07', '도덕', '중1~3', '자신과의 관계', '삶에서 직업이 갖는 의미와 가치를 파악하며, 사례 탐구를 통해 직업적 양심과 직업윤리의 필요성을 정당화할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-01', '도덕', '중1~3', '타인과의 관계', '정서적, 배려적 공동체로서 가정의 특성과 도덕적 기능을 파악하고, 가정에서 발생하는 갈등을 공감적인 소통과 민주적인 과정을 통해 해소하는 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-02', '도덕', '중1~3', '타인과의 관계', '친구의 의미와 가치를 삶의 맥락 속에서 탐구하고, 서로를 인격적으로 존중하는 친구 관계를 상상하며 이를 실현하는 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-03', '도덕', '중1~3', '타인과의 관계', '가상공간과 현실 세계에 대한 비교⋅분석을 바탕으로 가상공간에서 발생하는 도덕 문제들의 원인과 해결 방안을 제안하고, 타인을 존중하며 가상공간을 활용하는 태도를 함양한다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-04', '도덕', '중1~3', '타인과의 관계', '인간을 관계적 존재로 해석할 수 있는 이유에 근거하여 타인과의 관계에서 필요한 가치⋅덕목을 탐구하고, 타인의 생각과 감정에 공감하는 태도를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-05', '도덕', '중1~3', '타인과의 관계', '다양한 갈등 상황을 평화적으로 해결할 수 있는 방안을 모색하고, 폭력의 유형과 원인, 결과에 대한 분석을 바탕으로 일상의 폭력 상황에 대한 대처 능력을 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도02-06', '도덕', '중1~3', '타인과의 관계', '청소년기의 바람직한 성윤리를 탐구하여 내면화하고, 사회⋅문화적 차원에서 성의 의미를 파악하여 성에 대한 편견의 문제점을 분석하고 이를 바로잡는 의지를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-01', '도덕', '중1~3', '사회⋅공동체와의 관계', '인권을 존중해야 하는 도덕적 이유를 정당화하고, 인권 침해 사례에 대한 탐구를 통해 그 원인과 해결 방안을 도출함으로써 인권 감수성을 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-02', '도덕', '중1~3', '사회⋅공동체와의 관계', '외집단에 대한 편견을 비판적으로 분석하고, 타문화⋅타종교⋅타인종을 존중해야 하는 이유에 근거하여 차이와 다양성에 대한 열린 마음을 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-03', '도덕', '중1~3', '사회⋅공동체와의 관계', '북한에 대한 이해를 바탕으로 분단의 문제점을 분석하고, 도덕적 가치에 기초하여 통일의 의미를 재구성함으로써 바람직한 남북관계 및 통일의 방향을 제안할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-04', '도덕', '중1~3', '사회⋅공동체와의 관계', '정의로운 사회를 상상해보고, 이를 실현할 수 있는 정의의 원칙과 제도에 대한 다양한 의견들을 민주적인 방식으로 종합할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-05', '도덕', '중1~3', '사회⋅공동체와의 관계', '국가와 시민 사이에서 발생하는 윤리적 쟁점들을 탐구하고, 국가와 시민 사이의 바람직한 관계에 기초하여 국가와 시민의 역할을 재구성할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-06', '도덕', '중1~3', '사회⋅공동체와의 관계', '인류의 고통에 공감하며 지구적 차원의 다양한 도덕 문제들을 탐구하고, 해결 방안을 모색하여 실천하는 자세를 갖는다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도03-07', '도덕', '중1~3', '사회⋅공동체와의 관계', '현대 과학기술과 관련된 윤리적 쟁점의 분석을 통해 과학기술의 유용성과 한계를 인식하고, 과학기술의 바람직한 활용에 관한 관심과 책임 의식을 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도04-01', '도덕', '중1~3', '자연과의 관계', '인간 이외의 생명체를 도덕적으로 고려해야 하는 이유를 정당화하고, 생명을 가진 존재들이 겪는 고통에 공감하며 생명을 소중히 여기는 태도를 기른다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL),
('9도04-02', '도덕', '중1~3', '자연과의 관계', '자연에 대한 동양과 서양의 주요 입장들을 토대로 인간과 자연의 바람직한 관계를 도출하고, 환경 위기에 대한 윤리적 책임을 구체화하여 실천할 수 있다.', 5, NULL, '2022 개정', '교육부 고시 제2022-33호', NULL)
